const rows = [
 {transaction_id:'TXN001',customer_id:'CUST001',amount:1200,currency:'INR',status:'PAID'},
 {transaction_id:'TXN002',customer_id:'CUST002',amount:-350,currency:'INR',status:'PAID'},
 {transaction_id:'TXN003',customer_id:'CUST003',amount:'750',currency:'inr',status:'paid'},
 {transaction_id:'TXN004',customer_id:'',amount:500,currency:'INR',status:'PAID'},
 {transaction_id:'TXN005',customer_id:'CUST005',amount:999,currency:'USD',status:'PENDING'}
];
// Change TEST_CASE from 1 to 5 to test a different record.
// Only one transaction is sent to Groq per workflow execution.
const TEST_CASE = 1;
if (!Number.isInteger(TEST_CASE) || TEST_CASE < 1 || TEST_CASE > rows.length) {
  throw new Error('TEST_CASE must be between 1 and ' + rows.length);
}
return [{json:{transaction:rows[TEST_CASE - 1], test_case:TEST_CASE}}];

const t = $json.transaction;
const errors=[];
if (!/^TXN\d{3,}$/.test(String(t.transaction_id||''))) errors.push('Invalid transaction_id');
if (!/^CUST\d{3,}$/.test(String(t.customer_id||''))) errors.push('Invalid customer_id');
if (typeof t.amount !== 'number' || !Number.isFinite(t.amount) || t.amount <= 0) errors.push('Amount must be a positive number');
if (!['INR','USD','EUR'].includes(t.currency)) errors.push('Currency must be INR, USD, or EUR');
if (!['PAID','PENDING','FAILED'].includes(t.status)) errors.push('Status must be PAID, PENDING, or FAILED');
return {json:{original:t,initial_errors:errors,initial_valid:errors.length===0}};

// n8n Code Tool receives the AI Agent input as `query`.
let t;
try {
  const input = typeof query === 'undefined' ? {} : query;
  t = typeof input === 'string' ? JSON.parse(input) : input;
  if (t && typeof t === 'object' && t.transaction) t = t.transaction;
  if (!t || typeof t !== 'object' || Array.isArray(t)) throw new Error('Expected transaction object');
} catch (error) {
  return JSON.stringify({valid:false,errors:['Invalid JSON input: ' + error.message]});
}
const errors = [];
if (!/^TXN\d{3,}$/.test(String(t.transaction_id ?? ''))) errors.push('Invalid transaction_id');
if (!/^CUST\d{3,}$/.test(String(t.customer_id ?? ''))) errors.push('Invalid customer_id');
if (typeof t.amount !== 'number' || !Number.isFinite(t.amount) || t.amount <= 0) errors.push('Amount must be a positive number');
if (!['INR','USD','EUR'].includes(t.currency)) errors.push('Invalid currency');
if (!['PAID','PENDING','FAILED'].includes(t.status)) errors.push('Invalid status');
return JSON.stringify({valid:errors.length===0,errors});

// Deterministic final audit: never trust the model's status without checking.
const source = $('Validation Tool Initial').item.json;
const orig = source.original;
let r = $json.output ?? $json;
const errors = [];
try {
  if (typeof r === 'string') r = JSON.parse(r);
  if (r && typeof r.output === 'string') r = JSON.parse(r.output);
  else if (r && typeof r.output === 'object') r = r.output;
  if (!r || typeof r !== 'object' || Array.isArray(r)) throw new Error('Agent did not return an object');
} catch (e) {
  errors.push('Could not parse agent response: ' + e.message);
  r = {};
}
if (r.transaction_id !== orig.transaction_id) errors.push('Transaction ID changed');
if (r.customer_id !== orig.customer_id) errors.push('Customer ID changed');
if (!/^TXN\d{3,}$/.test(String(r.transaction_id ?? ''))) errors.push('Invalid transaction_id');
if (!/^CUST\d{3,}$/.test(String(r.customer_id ?? ''))) errors.push('Invalid customer_id');
if (typeof r.amount !== 'number' || !Number.isFinite(r.amount) || r.amount <= 0) errors.push('Invalid amount');
if (!['INR','USD','EUR'].includes(r.currency)) errors.push('Invalid currency');
if (!['PAID','PENDING','FAILED'].includes(r.payment_status)) errors.push('Invalid payment_status');
const amountSafe = r.amount === orig.amount ||
  (typeof orig.amount === 'string' && orig.amount.trim() !== '' && Number(orig.amount) === r.amount && r.amount > 0);
if (!amountSafe) errors.push('Unsafe amount change');
if (r.currency !== String(orig.currency ?? '').toUpperCase()) errors.push('Unsafe currency change');
if (r.payment_status !== String(orig.status ?? '').toUpperCase()) errors.push('Unsafe status change');
const validated = errors.length === 0;
return {json:{
  transaction_id: orig.transaction_id,
  customer_id: orig.customer_id,
  amount: validated ? r.amount : orig.amount,
  currency: validated ? r.currency : orig.currency,
  payment_status: validated ? r.payment_status : orig.status,
  audit_status: validated ? 'ACCEPTED' : 'REJECTED',
  validated,
  corrections: Array.isArray(r.corrections) ? r.corrections : [],
  issues: [...(Array.isArray(r.issues) ? r.issues : []), ...errors],
  reason: validated ? (r.reason || 'Passed deterministic validation') : errors.join('; '),
  initial_errors: source.initial_errors,
  validation_errors: errors,
  original_transaction: orig
}};
